import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Сжать одно изображение легко. Сжать пятьдесят — уже другая работа, и делать это по одному значит потерять полдня.</p>\n<p>Пакетное сжатие решает эту задачу. Вы перетаскиваете целую папку, выбираете пресет и скачиваете все сжатые изображения вместе одним архивом ZIP.</p>\n<p>Это руководство объясняет, как работает пакетный компрессор, когда его использовать и как получать согласованные результаты для всей партии. Всю партию можно обработать за один проход в инструменте <a href=\"/ru/paketnoe-szhatie-izobrazheniy/\">Пакетный компрессор изображений</a>: перетащите папку, выберите пресет и скачайте один ZIP-архив.</p>\n<h2 id=\"what-is-bulk-compression\">Что такое пакетное сжатие</h2>\n<p>Пакетное сжатие применяет одни и те же настройки ко многим изображениям сразу. Вместо открытия каждого файла отдельно вы обрабатываете весь набор за один проход.</p>\n<p>Инструмент проходит очередь по одному изображению, показывая живой индикатор прогресса. Вы видите, какие файлы готовы, какие обрабатываются и сколько места сэкономлено.</p>\n<p>Каждое изображение сжимается отдельно. Инструмент находит лучшее качество для каждого файла, поэтому простой портрет и детальный пейзаж получают разную обработку.</p>\n<p>Результаты скачиваются вместе архивом ZIP. Так набор остаётся организованным и готовым к загрузке одним движением.</p>\n<h2 id=\"how-it-works\">Как это работает</h2>\n<p>Перетащите изображения в область загрузки или выберите целую папку. Принимаются JPG, PNG, WebP и HEIC, и смешанные партии работают нормально.</p>\n<p>Выберите пресет: «Сбалансированный», «Меньший файл» или «Высокое качество». Каждый пресет задаёт начальное качество и подход к сжатию для всей партии.</p>\n<p>Инструмент обрабатывает очередь с живым индикатором прогресса. Вы видите, какие файлы готовы, какие выполняются и сколько общего размера сэкономлено.</p>\n<p>Просмотрите отдельные результаты перед скачиванием. Нажмите на любое готовое изображение, чтобы проверить его качество в полном размере.</p>\n<p>Когда партия завершена, нажмите «Скачать все», чтобы получить один архив ZIP со всеми сжатыми изображениями внутри.</p>\n<h2 id=\"presets-explained\">Пресеты: объяснение</h2>\n<p>«Сбалансированный» — пресет по умолчанию. Он начинается с качества 70 процентов и стремится к хорошей середине между размером файла и визуальным качеством.</p>\n<p>«Меньший файл» сильнее сжимает изображения. Он подходит для миниатюр и изображений, которые показываются маленькими.</p>\n<p>«Высокое качество» сохраняет максимум деталей. Он подходит для витринных изображений, портфолио и работ, которые рассматривают в полном размере.</p>\n<p>Пресет задаёт начальную точку, а не фиксированный результат. Каждое изображение всё равно оптимизируется отдельно в рамках подхода пресета.</p>\n<p>Начинайте со «Сбалансированного» для большинства задач. Переходите на «Меньший файл» для миниатюр и на «Высокое качество» для витринных изображений.</p>\n<h2 id=\"when-to-use-bulk\">Когда использовать пакетный режим</h2>\n<p>Переезд блога — классический случай. Перенос пятидесяти старых миниатюр на новый сайт означает пятьдесят сжатий, а партия справляется за минуты.</p>\n<p>Подходит любая повторяющаяся задача. Если вы сжимаете один и тот же тип изображений каждую неделю, пресет партии экономит время в каждом круге.</p>\n<p>Каталоги магазинов — ещё один случай. Десятки фото товаров с одинаковыми настройками выглядят согласованно и загружаются быстро.</p>\n<p>Фотоархивы тоже выигрывают. Сотни снимков из отпуска, сжатые одной партией, занимают в разы меньше места.</p>\n<p>Одиночные изображения в пакетном режиме не нуждаются. Для одного фото инструменты с точным лимитом в килобайтах дают более точный контроль.</p>\n<h2 id=\"batch-vs-target-tools\">Пакетный режим против инструментов с точным лимитом</h2>\n<p>Пакетный компрессор работает по пресету качества, а не по точному размеру файла. Он делает изображения меньше, не обещая конкретного числа килобайт.</p>\n<p>Инструменты с лимитом в килобайтах работают наоборот. Они гарантируют, что файл окажется меньше 50, 100, 200 или 500 КБ, используя бинарный поиск качества.</p>\n<p>Используйте пакетный режим, когда цель — просто меньшие файлы. Используйте инструмент с лимитом, когда портал или платформа требуют точное значение.</p>\n<p><a href=\"/ru/szhat-izobrazhenie-do-tselego-razmera/\">Компрессор до точного размера файла</a> соединяет оба мира. Он сжимает партии до точного нестандартного размера, сочетая удобство партии с точными лимитами.</p>\n<p>Для оптимизации сайта с пресетами и HTML-выводом лучше подходит <a href=\"/ru/optimizirovat-izobrazheniya-dlya-sajta/\">оптимизатор изображений для сайта</a>.</p>\n<h2 id=\"quality-in-batches\">Качество в партиях</h2>\n<p>Каждое изображение в партии оптимизируется отдельно. Простое фото получает другую обработку, чем детальный пейзаж, даже при одном пресете.</p>\n<p>Проверяйте образцы из каждой партии. Одно плохое изображение среди пятидесяти легко пропустить, а стыдно будет всей подборке.</p>\n<p>Если одно изображение выглядит мягким, запустите его отдельно с другим пресетом. Не нужно переделывать всю партию из-за одного файла.</p>\n<p>Смешанные партии — фото, скриншоты, графика — требуют внимания. Один пресет не подходит всем типам одинаково хорошо.</p>\n<p>Разделяйте партии по типу содержимого, когда это возможно. Партия только фото и партия только скриншотов дают более предсказуемые результаты.</p>\n<h2 id=\"formats-in-batches\">Форматы в партиях</h2>\n<p>Смешанные партии работают нормально: JPG, PNG, WebP и HEIC можно загружать вместе. Инструмент обрабатывает каждый файл по его типу.</p>\n<p>Фото в PNG — частая ловушка в партиях. PNG с фото внутри весит много, и автоконвертация в JPG или WebP решает проблему.</p>\n<p>Графика с прозрачностью требует осторожности. Конвертация в JPG уничтожит прозрачность, поэтому такие файлы держите в PNG.</p>\n<p>Проверьте форматы результатов перед скачиванием архива. Один файл не того формата может не подойти платформе.</p>\n<p>Когда сомневаетесь, держите партию однородной: только фото или только графика. Так настройки предсказуемы.</p>\n<h2 id=\"zip-workflow\">Работа с ZIP-архивом</h2>\n<p>Результаты партии скачиваются одним архивом ZIP. Распакуйте его в папку с названием проекта, а не в общую папку «Загрузки».</p>\n<p>Проверьте содержимое архива после распаковки. Убедитесь, что все файлы на месте и ни один не повреждён.</p>\n<p>Называйте распакованные файлы понятно. Архив с общими именами создаёт путаницу при загрузке на сайт.</p>\n<p>Храните архив как резервную копию сжатых файлов. Если понадобится та же партия снова, архив уже готов.</p>\n<p>Удаляйте архив после успешной публикации, если место на диске ограничено. Сжатые копии легко сделать заново с оригиналов.</p>\n<h2 id=\"phone-batches\">Партии на телефоне</h2>\n<p>Пакетное сжатие работает и на телефоне, но с ограничениями. Телефоны слабее ноутбуков, и большие партии обрабатываются медленнее.</p>\n<p>Разбивайте большие партии на части по десять-двадцать файлов. Так телефон не перегревается и не исчерпывает память.</p>\n<p>Держите браузер открытым, пока партия выполняется. Переключение на другое приложение может прервать обработку.</p>\n<p>Скачивайте архив ZIP в приложение «Файлы» и распаковывайте его там. Проверьте несколько файлов перед загрузкой на сайт.</p>\n<p>Для больших партий — пятьдесят файлов и больше — используйте ноутбук. Телефон подходит для маленьких партий в дороге.</p>\n<h2 id=\"common-mistakes\">Типичные ошибки</h2>\n<p>Неправильный пресет тратит время. «Меньший файл» для портфолио делает работу плохой, а «Высокое качество» для миниатюр тратит трафик.</p>\n<p>Начинать с уже сжатых файлов — ещё одна ошибка. Каждый круг добавляет повреждения, поэтому всегда используйте оригиналы.</p>\n<p>Забывать проверять образцы — частая ошибка. Размер партии может быть правильным, а одно изображение — размытым.</p>\n<p>Смешивать типы содержимого бездумно — тоже ошибка. Фото, скриншоты и графика нуждаются в разных настройках.</p>\n<p>И не удаляйте оригиналы после партии. Правила меняются, и свежая партия с оригиналов делается за минуты.</p>\n<h2 id=\"privacy-in-bulk\">Конфиденциальность в пакетном режиме</h2>\n<p>Сжатие полностью происходит в вашем браузере. Ваши фото никогда не загружаются на сервер, даже когда файлов пятьдесят.</p>\n<p>Инструмент также удаляет скрытые метаданные, включая GPS-метки. Это важно, когда в партии — личные фото или фото клиентов.</p>\n<p>Для клиентских работ удаление метаданных обязательно. Неопубликованные продукты и частные места не должны просачиваться через метаданные.</p>\n<p>Проверьте один файл из партии на метаданные после сжатия. Убедитесь, что GPS-метки действительно удалены.</p>\n<p>Работайте в приватном окне, если компьютер общий. Так файлы и история не останутся в браузере после вас.</p>\n<h2 id=\"batch-summary\">Итоги партии</h2>\n<p>Когда партия завершена, инструмент показывает итоги общей экономии. Он сообщает исходный общий размер, сжатый общий размер и процент экономии.</p>\n<p>Итоги делают пользу наглядной. Пятьдесят изображений, упавших с 200 МБ до 15 МБ, — это конкретный результат, а не абстракция.</p>\n<p>Запишите итоги для отчёта. Числа убеждают коллег и клиентов лучше любых аргументов.</p>\n<p>Сравните итоги разных пресетов на одной партии. Так вы узнаете, какой пресет даёт лучшую экономию для вашего типа изображений.</p>\n<p>Используйте итоги для планирования: зная среднюю экономию, вы сможете оценить вес будущих партий заранее.</p>\n<h2 id=\"recompress-single\">Повторное сжатие одного файла</h2>\n<p>Если один файл в партии выглядит плохо, не переделывайте всю партию. Запустите только этот файл отдельно с другими настройками.</p>\n<p>Попробуйте другой пресет или другой формат. Часто смена с PNG на JPG решает проблему одного файла.</p>\n<p>Проверьте исходник этого файла. Возможно, проблема не в настройках, а в плохом исходном снимке.</p>\n<p>Замените файл в архиве на исправленную версию. Держите имена одинаковыми, чтобы не сломать ссылки на сайте.</p>\n<p>Запишите, что сработало для этого файла. В следующий раз вы сразу выберете правильные настройки.</p>\n<h2 id=\"dimension-consistency\">Согласованность размеров</h2>\n<p>Партия с одинаковыми размерами выглядит аккуратно на сайте. Сетка из изображений разного размера выглядит неряшливо и заставляет браузер перестраивать страницу.</p>\n<p>Обрежьте изображения под одно соотношение до сжатия. Одинаковые пропорции — основа аккуратной сетки.</p>\n<p>Пакетный компрессор не выравнивает размеры сам: он сжимает то, что вы дали. Подготовка размеров — ваша задача.</p>\n<p>Проверьте размеры нескольких файлов после партии. Один файл не того размера испортит всю сетку.</p>\n<p>Для карточек товаров и миниатюр блога согласованность размеров важнее, чем для отдельных статей.</p>\n<h2 id=\"backup-strategy\">Стратегия резервных копий</h2>\n<p>Храните оригиналы отдельно от сжатых копий. Папка «оригиналы» и папка «для сайта» не должны смешиваться.</p>\n<p>Делайте резервную копию оригиналов перед каждой большой партией. Один сбой не должен уничтожить единственные копии.</p>\n<p>Называйте папки по датам и проектам. Папка «2026-11-каталог» находится за секунды, а «Новая папка» — никогда.</p>\n<p>Проверяйте резервные копии время от времени. Копия, которую нельзя открыть, — это не копия.</p>\n<p>Когда нужна партия другого размера, делайте её с оригиналов. Не пережимайте готовую партию.</p>\n<h2 id=\"seasonal-batches\">Сезонные партии</h2>\n<p>Магазины и блоги готовят партии по сезонам: новогодние товары, летние коллекции, осенние статьи. Одинаковые пресеты из сезона в сезон дают согласованный вид.</p>\n<p>Запишите пресет для каждого сезона. В следующем году вы просто повторите настройки, а не будете гадать заново.</p>\n<p>Храните сжатые файлы вместе с материалом, к которому они относятся. Общая папка миниатюр делает повторное использование лёгким.</p>\n<p>Проверяйте изображения перед каждым повторным использованием. Миниатюра, хорошая в прошлом году, может не подойти под нынешнюю вёрстку.</p>\n<p>Никогда не сжимайте повторно используемый файл. Если нужен новый размер, вернитесь к оригиналу.</p>\n<h2 id=\"accessibility-batches\">Доступность в партиях</h2>\n<p>Сжатые изображения всё равно нуждаются в описательном alt-тексте. Поисковики не видят картинку, они читают её описание.</p>\n<p>Пишите alt-текст для каждого изображения партии, а не один общий для всех. Одинаковый alt-текст для разных картинок бесполезен.</p>\n<p>Высокий контраст помогает всем зрителям. Изображение с чётким объектом на фоне легче увидеть, включая людей со слабым зрением.</p>\n<p>Не полагайтесь только на цвет. Форма, использующая цвет для разделения областей, становится запутанной, когда сжатие приглушает цвета.</p>\n<p>Сжатие и доступность идут вместе. Чёткий исходник с высоким контрастом сжимается лучше и легче читается каждым зрителем.</p>\n<h2 id=\"final-check\">Финальная проверка</h2>\n<p>Проверьте несколько образцов из партии в полном размере. Лица чёткие, текст читаем, края не обрезаны.</p>\n<p>Проверьте общий вес архива. Он должен соответствовать ожиданиям: пятьдесят изображений по 100 КБ — это около 5 МБ.</p>\n<p>Проверьте форматы результатов. Каждый файл должен быть в формате, который принимает ваша платформа.</p>\n<p>Проверьте имена файлов. Понятные имена экономят время при загрузке на сайт.</p>\n<p>Только после этого публикуйте партию. Двухминутная проверка сейчас лучше, чем плохие картинки на живом сайте.</p>\n<p>Когда готовите большую партию для переезда блога, начните с самых посещаемых статей. Их изображения важнее всего, а остальные можно обработать позже.</p>\n<p>Разбивайте большие партии по смыслу: одна категория товаров — одна партия. Так настройки подходят каждой группе, а файлы не смешиваются.</p>\n<p>Проверяйте итоги каждой партии и записывайте их. Со временем вы узнаете среднюю экономию и сможете точнее планировать будущие партии.</p>\n<p>Если в партии есть изображения с прозрачностью, держите их отдельно. Пакетная конвертация может уничтожить прозрачность, если формат выбран неверно.</p>\n<p>Для сезонных партий — новогодние товары, летние коллекции — записывайте пресет и настройки. В следующем году вы просто повторите их.</p>\n<p>Обучите коллег, которые делают партии. Общая заметка с пресетами и правилами именования экономит часы объяснений.</p>\n<p>Не забывайте про проверку образцов: именно в больших партиях прячутся ошибки. Пять минут на проверку экономят пять часов на переделку.</p>\n<p>Когда партия готова, сделайте паузу и посмотрите на результаты свежим взглядом. Уставший глаз пропускает то, что заметит свежий.</p>\n<p>И помните: пакетный режим — это инструмент для похожих файлов. Когда файлы очень разные, обрабатывайте их по одному.</p>\n<p>Когда партия скачана архивом ZIP, проверьте его содержимое сразу после распаковки. Убедитесь, что все файлы на месте и ни один не повреждён.</p>\n<p>Называйте распакованные файлы понятно: имя товара или статьи плюс размер. Архив с общими именами создаёт путаницу при загрузке на сайт.</p>\n<p>Оценивайте время партии заранее: десять файлов занимают около минуты, а пятьдесят — несколько минут. Закладывайте время и на проверку образцов.</p>\n<p>Если телефон перегревается во время большой партии, разбейте её на части. Маленькие партии безопаснее для слабых устройств.</p>\n<p>Файлы, которые не удались, соберите в отдельный список и запустите маленькой партией с другими настройками. Часто помогает смена пресета или формата.</p>\n<p>Добавляйте alt-текст каждому изображению партии при загрузке на сайт. Одинаковый alt-текст для разных картинок бесполезен, пишите для каждой свой.</p>\n<p>Когда отправляете партию клиенту, приложите итоги: исходный вес, итоговый вес и процент экономии. Числа убеждают лучше слов.</p>\n<p>Чек-лист перед запуском партии: оригиналы на месте, пресет выбран, тестовая пятёрка проверена, папка для распаковки готова.</p>\n<p>Если партия делается для переезда блога, начните с самых посещаемых статей. Их изображения важнее всего, остальные можно обработать позже.</p>\n<p>Если партия делается для клиента, согласуйте пресет заранее: покажите ему тестовые файлы и получите одобрение до запуска всей партии.</p>\n<p>Практические шаги читайте в статье <a href=\"/ru/blog/kak-szhat-neskolko-izobrazheniy-srazu/\">Как сжать несколько изображений сразу</a>. Лучшие практики — в статье <a href=\"/ru/blog/paketnoe-szhatie-izobrazheniy-luchshie-praktiki/\">Пакетное сжатие изображений: лучшие практики</a>. Для точных лимитов используйте <a href=\"/ru/szhat-izobrazhenie-do-tselego-razmera/\">компрессор до точного размера файла</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Сколько изображений можно сжать одной пакетной партией?","answer":"Жёсткого лимита на число файлов нет, но очень большие партии лучше разбивать на части по 20–50 файлов. Так браузер работает стабильнее, а проверка образцов занимает меньше времени. На телефоне держите партии ещё меньше — по 10–20 файлов."},{"question":"Меняет ли пакетное сжатие размеры моих изображений?","answer":"Нет, если вы сами этого не задали: пакетный компрессор работает по пресету качества и сохраняет размеры. Размеры уменьшаются, только когда это нужно для достижения цели в инструментах с точным лимитом. Проверьте размеры результатов, если платформа требует точные пиксели."},{"question":"Чем отличаются три пакетных пресета?","answer":"«Сбалансированный» начинается с качества 70 процентов и даёт середину между размером и качеством. «Меньший файл» сжимает сильнее и подходит для миниатюр. «Высокое качество» сохраняет максимум деталей и подходит для витринных изображений и портфолио."},{"question":"Можно ли добавить ещё изображения после завершения партии?","answer":"Нет, завершённая партия закрыта. Добавьте новые файлы и запустите новую партию с теми же настройками. Чтобы результаты совпадали, используйте тот же пресет, что и в первой партии."},{"question":"Почему одно изображение в партии показало предупреждение, что оно стало больше?","answer":"Файл может вырасти, когда его перекодируют в формат, который ему плохо подходит — например, фото в PNG. Инструмент честно предупреждает об этом. Переключите такой файл на JPG или WebP и запустите его отдельно."},{"question":"Можно ли сжимать анимированные GIF в пакетной партии?","answer":"Нет, для GIF есть отдельный инструмент: пакетный компрессор работает с обычными изображениями. Анимированные GIF сжимайте в инструменте сжатия GIF, где учитываются палитра, кадры и частота кадров."}];
